  { denyRuleNewType :: !(E'Type2) -- ^ /Required/ "type" - The type of deny rule.
  , denyRuleNewData :: !(Text) -- ^ /Required/ "data" - The content of the rule.  If a domain type rule then an example would be google.com. For a begins with type an example would be msgid-.  For the email typer an example would be user@server.com.
  , denyRuleNewUser :: !(Maybe Text) -- ^ "user" - Mail account username that will be tied to this rule.  If not specified the first active mail order will be used.
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON DenyRuleNew
instance A.FromJSON DenyRuleNew where
  parseJSON = A.withObject "DenyRuleNew" $ \o ->
    DenyRuleNew
      <$> (o .:  "type")
      <*> (o .:  "data")
      <*> (o .:? "user")

-- | ToJSON DenyRuleNew
instance A.ToJSON DenyRuleNew where
  toJSON DenyRuleNew {..} =
   _omitNulls
      [ "type" .= denyRuleNewType
      , "data" .= denyRuleNewData
      , "user" .= denyRuleNewUser
      ]

-- | FromForm DenyRuleNew
instance WH.FromForm DenyRuleNew where
  fromForm f =
    DenyRuleNew
      <$> (WH.parseUnique "type" f)
      <*> (WH.parseUnique "data" f)
      <*> (WH.parseMaybe "user" f)

-- | ToForm DenyRuleNew
instance WH.ToForm DenyRuleNew where
  toForm DenyRuleNew {..} =
    WH.Form $ HM.fromList $ P.catMaybes $
      [ _toFormItem "type" (Just denyRuleNewType)
      , _toFormItem "data" (Just denyRuleNewData)
      , _toFormItem "user" (denyRuleNewUser)
      ]

-- | Construct a value of type 'DenyRuleNew' (by applying it's required fields, if any)
mkDenyRuleNew
  :: E'Type2 -- ^ 'denyRuleNewType': The type of deny rule.
  -> Text -- ^ 'denyRuleNewData': The content of the rule.  If a domain type rule then an example would be google.com. For a begins with type an example would be msgid-.  For the email typer an example would be user@server.com.
  -> DenyRuleNew
mkDenyRuleNew denyRuleNewType denyRuleNewData =
  DenyRuleNew
  { denyRuleNewType
  , denyRuleNewData
  , denyRuleNewUser = Nothing
  }

