-- ** MailLog
-- | MailLog
-- MailLog
-- 
-- Paginated mail log response.  Contains the full matched count (`total`) plus a page of `MailLogEntry` records.  The `total` reflects the grouping mode: with `groupby=recipient` it counts delivery attempts, with `groupby=message` it counts unique messages.
data MailLog = MailLog
  { mailLogTotal :: !(Int) -- ^ /Required/ "total" - Total number of log entries that match the supplied filters, regardless of &#x60;skip&#x60; and &#x60;limit&#x60;.  Reflects the &#x60;groupby&#x60; mode.
  , mailLogSkip :: !(Int) -- ^ /Required/ "skip" - The &#x60;skip&#x60; value used for this page (echoed from the request).
  , mailLogLimit :: !(Int) -- ^ /Required/ "limit" - The &#x60;limit&#x60; value used for this page (echoed from the request).
  , mailLogEmails :: !([MailLogEntry]) -- ^ /Required/ "emails"
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON MailLog
instance A.FromJSON MailLog where
  parseJSON = A.withObject "MailLog" $ \o ->
    MailLog
      <$> (o .:  "total")
      <*> (o .:  "skip")
      <*> (o .:  "limit")
      <*> (o .:  "emails")

-- | ToJSON MailLog
instance A.ToJSON MailLog where
  toJSON MailLog {..} =
   _omitNulls
      [ "total" .= mailLogTotal
      , "skip" .= mailLogSkip
      , "limit" .= mailLogLimit
      , "emails" .= mailLogEmails
      ]


-- | Construct a value of type 'MailLog' (by applying it's required fields, if any)
mkMailLog
  :: Int -- ^ 'mailLogTotal': Total number of log entries that match the supplied filters, regardless of `skip` and `limit`.  Reflects the `groupby` mode.
  -> Int -- ^ 'mailLogSkip': The `skip` value used for this page (echoed from the request).
  -> Int -- ^ 'mailLogLimit': The `limit` value used for this page (echoed from the request).
  -> [MailLogEntry] -- ^ 'mailLogEmails' 
  -> MailLog
mkMailLog mailLogTotal mailLogSkip mailLogLimit mailLogEmails =
  MailLog
  { mailLogTotal
  , mailLogSkip
  , mailLogLimit
  , mailLogEmails
  }

-- ** MailLogEntry
-- | MailLogEntry
-- MailLogEntry
-- 
-- A single email record in the mail log.  Combines data from the message store (envelope metadata), the queue release table (delivery status and response), and the sender delivery table (MX routing details).  When `groupby=recipient` each row represents one delivery attempt; when `groupby=message` delivery fields reflect one arbitrary recipient.
data MailLogEntry = MailLogEntry
  { mailLogEntryId :: !(Int) -- ^ /Required/ "_id" - Internal auto-increment database row ID.
  , mailLogEntryId :: !(Text) -- ^ /Required/ "id" - The relay-assigned mail ID (18-19 hex characters).  Matches the &#x60;mailid&#x60; filter parameter and the &#x60;text&#x60; value returned by send endpoints.
  , mailLogEntryFrom :: !(Text) -- ^ /Required/ "from" - SMTP envelope &#x60;MAIL FROM&#x60; address.
  , mailLogEntryTo :: !(Text) -- ^ /Required/ "to" - SMTP envelope &#x60;RCPT TO&#x60; address.
  , mailLogEntryCreated :: !(Text) -- ^ /Required/ "created" - Human-readable creation timestamp in &#x60;YYYY-MM-DD HH:MM:SS&#x60; format.
  , mailLogEntryTime :: !(Int) -- ^ /Required/ "time" - Unix timestamp of message acceptance.  Corresponds to the &#x60;startDate&#x60; and &#x60;endDate&#x60; filter parameters.
  , mailLogEntryUser :: !(Text) -- ^ /Required/ "user" - The SMTP AUTH username used to submit the message (e.g. &#x60;mb5658&#x60;).
  , mailLogEntryTranstype :: !(Text) -- ^ /Required/ "transtype" - SMTP transaction type negotiated with the relay.
  , mailLogEntryOrigin :: !(Text) -- ^ /Required/ "origin" - IP address of the client that submitted the message to the relay.
  , mailLogEntryInterface :: !(Text) -- ^ /Required/ "interface" - Relay interface name that accepted the message.
  , mailLogEntrySubject :: !(Maybe Text) -- ^ "subject" - The &#x60;Subject&#x60; header value.  MIME-encoded subjects (UTF-8, ISO-8859, US-ASCII) are automatically decoded.
