-- ** SendMail
-- | SendMail
-- SendMail
-- 
-- Details for an Email
data SendMail = SendMail
  { sendMailTo :: !(Text) -- ^ /Required/ "to" - The Contact whom is the primary recipient of this email.
  , sendMailFrom :: !(Text) -- ^ /Required/ "from" - The contact whom is the this email is from.
  , sendMailSubject :: !(Text) -- ^ /Required/ "subject" - The subject or title of the email
  , sendMailBody :: !(Text) -- ^ /Required/ "body" - The main email contents.
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON SendMail
instance A.FromJSON SendMail where
  parseJSON = A.withObject "SendMail" $ \o ->
    SendMail
      <$> (o .:  "to")
      <*> (o .:  "from")
      <*> (o .:  "subject")
      <*> (o .:  "body")

-- | ToJSON SendMail
instance A.ToJSON SendMail where
  toJSON SendMail {..} =
   _omitNulls
      [ "to" .= sendMailTo
      , "from" .= sendMailFrom
      , "subject" .= sendMailSubject
      , "body" .= sendMailBody
      ]

-- | FromForm SendMail
instance WH.FromForm SendMail where
  fromForm f =
    SendMail
      <$> (WH.parseUnique "to" f)
      <*> (WH.parseUnique "from" f)
      <*> (WH.parseUnique "subject" f)
      <*> (WH.parseUnique "body" f)

-- | ToForm SendMail
instance WH.ToForm SendMail where
  toForm SendMail {..} =
    WH.Form $ HM.fromList $ P.catMaybes $
      [ _toFormItem "to" (Just sendMailTo)
      , _toFormItem "from" (Just sendMailFrom)
      , _toFormItem "subject" (Just sendMailSubject)
      , _toFormItem "body" (Just sendMailBody)
      ]

-- | Construct a value of type 'SendMail' (by applying it's required fields, if any)
mkSendMail
  :: Text -- ^ 'sendMailTo': The Contact whom is the primary recipient of this email.
  -> Text -- ^ 'sendMailFrom': The contact whom is the this email is from.
  -> Text -- ^ 'sendMailSubject': The subject or title of the email
  -> Text -- ^ 'sendMailBody': The main email contents.
  -> SendMail
mkSendMail sendMailTo sendMailFrom sendMailSubject sendMailBody =
  SendMail
  { sendMailTo
  , sendMailFrom
  , sendMailSubject
  , sendMailBody
  }

-- ** SendMailAdv
-- | SendMailAdv
-- SendMailAdv
-- 
-- Details for an Email
data SendMailAdv = SendMailAdv
  { sendMailAdvSubject :: !(Text) -- ^ /Required/ "subject" - The subject or title of the email
  , sendMailAdvBody :: !(Text) -- ^ /Required/ "body" - The main email contents.
  , sendMailAdvFrom :: !(EmailAddressName) -- ^ /Required/ "from"
  , sendMailAdvTo :: !([EmailAddressName]) -- ^ /Required/ "to" - A list of destionation email addresses to send this to
  , sendMailAdvReplyto :: !(Maybe [EmailAddressName]) -- ^ "replyto" - (optional) A list of email addresses that specify where replies to the email should be sent instead of the _from_ address.
  , sendMailAdvCc :: !(Maybe [EmailAddressName]) -- ^ "cc" - (optional) A list of email addresses to carbon copy this message to.  They are listed on the email and anyone getting the email can see this full list of Contacts who received the email as well.
  , sendMailAdvBcc :: !(Maybe [EmailAddressName]) -- ^ "bcc" - (optional) list of email addresses that should receive copies of the email.  They are hidden on the email and anyone gettitng the email would not see the other people getting the email in this list.
  , sendMailAdvAttachments :: !(Maybe [MailAttachment]) -- ^ "attachments" - (optional) File attachments to include in the email.  The file contents must be base64 encoded!
  , sendMailAdvId :: !(Maybe Integer) -- ^ "id" - (optional)  ID of the Mail order within our system to use as the Mail Account.
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON SendMailAdv
instance A.FromJSON SendMailAdv where
  parseJSON = A.withObject "SendMailAdv" $ \o ->
    SendMailAdv
      <$> (o .:  "subject")
      <*> (o .:  "body")
      <*> (o .:  "from")
      <*> (o .:  "to")
      <*> (o .:? "replyto")
      <*> (o .:? "cc")
      <*> (o .:? "bcc")
      <*> (o .:? "attachments")
      <*> (o .:? "id")

-- | ToJSON SendMailAdv
instance A.ToJSON SendMailAdv where
  toJSON SendMailAdv {..} =
   _omitNulls
      [ "subject" .= sendMailAdvSubject
      , "body" .= sendMailAdvBody
      , "from" .= sendMailAdvFrom
      , "to" .= sendMailAdvTo
      , "replyto" .= sendMailAdvReplyto
      , "cc" .= sendMailAdvCc
      , "bcc" .= sendMailAdvBcc
      , "attachments" .= sendMailAdvAttachments
      , "id" .= sendMailAdvId
      ]


-- | Construct a value of type 'SendMailAdv' (by applying it's required fields, if any)
mkSendMailAdv
  :: Text -- ^ 'sendMailAdvSubject': The subject or title of the email
  -> Text -- ^ 'sendMailAdvBody': The main email contents.
  -> EmailAddressName -- ^ 'sendMailAdvFrom' 
  -> [EmailAddressName] -- ^ 'sendMailAdvTo': A list of destionation email addresses to send this to
  -> SendMailAdv
mkSendMailAdv sendMailAdvSubject sendMailAdvBody sendMailAdvFrom sendMailAdvTo =
  SendMailAdv
  { sendMailAdvSubject
  , sendMailAdvBody
  , sendMailAdvFrom
  , sendMailAdvTo
  , sendMailAdvReplyto = Nothing
  , sendMailAdvCc = Nothing
  , sendMailAdvBcc = Nothing
  , sendMailAdvAttachments = Nothing
  , sendMailAdvId = Nothing
  }

