-- ** SslOrderRequest
-- | SslOrderRequest
-- Request body to validate (putSsl) or place (addSsl) an SSL certificate order. Contact fields default from the account if omitted. Package ids come from getNewSsl.serviceTypes.
data SslOrderRequest = SslOrderRequest
  { sslOrderRequestSsl :: !(Int) -- ^ /Required/ "ssl" - SSL package service type id from getNewSsl.serviceTypes.
  , sslOrderRequestHostname :: !(Text) -- ^ /Required/ "hostname" - Domain the certificate is issued for. Wildcard certs require *.domain.com format.
  , sslOrderRequestApproverEmail :: !(Text) -- ^ /Required/ "approver_email" - Domain-control approver email (required for all SSL orders).
  , sslOrderRequestFrequency :: !(Maybe Int) -- ^ "frequency" - Billing frequency in months (12, 24, or 36).
  , sslOrderRequestCoupon :: !(Maybe Text) -- ^ "coupon" - Coupon code.
  , sslOrderRequestCsrType :: !(Maybe E'CsrType) -- ^ "csr_type" - Whether the CSR is server-generated or customer-provided.
  , sslOrderRequestCsr :: !(Maybe Text) -- ^ "csr" - PEM-encoded CSR (&gt;&#x3D; 2048-bit) when csr_type&#x3D;provided.
  , sslOrderRequestFirstname :: !(Maybe Text) -- ^ "firstname" - Contact first name (defaults from account).
  , sslOrderRequestLastname :: !(Maybe Text) -- ^ "lastname" - Contact last name (defaults from account).
  , sslOrderRequestEmail :: !(Maybe Text) -- ^ "email" - Contact email (defaults from account).
  , sslOrderRequestAddress :: !(Maybe Text) -- ^ "address" - Contact address (defaults from account).
  , sslOrderRequestCity :: !(Maybe Text) -- ^ "city" - Contact city (defaults from account).
  , sslOrderRequestState :: !(Maybe Text) -- ^ "state" - Contact state/region (defaults from account).
  , sslOrderRequestZip :: !(Maybe Text) -- ^ "zip" - Contact postal code (defaults from account).
  , sslOrderRequestCountry :: !(Maybe Text) -- ^ "country" - Contact country (defaults from account).
  , sslOrderRequestPhone :: !(Maybe Text) -- ^ "phone" - Contact phone (defaults from account).
  , sslOrderRequestCompany :: !(Maybe Text) -- ^ "company" - Contact company/organization (defaults from account).
  , sslOrderRequestDepartment :: !(Maybe Text) -- ^ "department" - Contact department (defaults to Administration).
  , sslOrderRequestAgency :: !(Maybe Text) -- ^ "agency" - EV certificate incorporating agency (only for EV packages).
  , sslOrderRequestBusinessCategory :: !(Maybe Text) -- ^ "business_category" - EV certificate business category (only for EV packages).
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON SslOrderRequest
instance A.FromJSON SslOrderRequest where
  parseJSON = A.withObject "SslOrderRequest" $ \o ->
