      <*> (o .:? "frequency")
      <*> (o .:? "coupon")
      <*> (o .:? "csr_type")
      <*> (o .:? "csr")
      <*> (o .:? "firstname")
      <*> (o .:? "lastname")
      <*> (o .:? "email")
      <*> (o .:? "address")
      <*> (o .:? "city")
