  , vpsRowVpsHostname :: !(Text) -- ^ /Required/ "vps_hostname" - The hostname of the vps.
  , vpsRowVpsIp :: !(Text) -- ^ /Required/ "vps_ip" - The ip of the vps.
  , vpsRowVpsStatus :: !(Text) -- ^ /Required/ "vps_status" - The status of the vps.
  , vpsRowServicesName :: !(Text) -- ^ /Required/ "services_name" - The services name of the vps.
  , vpsRowVpsComment :: !(Text) -- ^ /Required/ "vps_comment" - The comment of the vps.
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON VpsRow
instance A.FromJSON VpsRow where
  parseJSON = A.withObject "VpsRow" $ \o ->
    VpsRow
      <$> (o .:  "vps_id")
      <*> (o .:  "vps_name")
      <*> (o .:  "repeat_invoices_cost")
      <*> (o .:  "vps_hostname")
      <*> (o .:  "vps_ip")
      <*> (o .:  "vps_status")
      <*> (o .:  "services_name")
      <*> (o .:  "vps_comment")

-- | ToJSON VpsRow
instance A.ToJSON VpsRow where
  toJSON VpsRow {..} =
   _omitNulls
      [ "vps_id" .= vpsRowVpsId
      , "vps_name" .= vpsRowVpsName
      , "repeat_invoices_cost" .= vpsRowRepeatInvoicesCost
      , "vps_hostname" .= vpsRowVpsHostname
      , "vps_ip" .= vpsRowVpsIp
      , "vps_status" .= vpsRowVpsStatus
      , "services_name" .= vpsRowServicesName
      , "vps_comment" .= vpsRowVpsComment
      ]


-- | Construct a value of type 'VpsRow' (by applying it's required fields, if any)
mkVpsRow
  :: Text -- ^ 'vpsRowVpsId': The id of the vps.
  -> Text -- ^ 'vpsRowVpsName': The name of the vps.
  -> Text -- ^ 'vpsRowRepeatInvoicesCost': The repeat invoices cost of the vps.
  -> Text -- ^ 'vpsRowVpsHostname': The hostname of the vps.
  -> Text -- ^ 'vpsRowVpsIp': The ip of the vps.
  -> Text -- ^ 'vpsRowVpsStatus': The status of the vps.
  -> Text -- ^ 'vpsRowServicesName': The services name of the vps.
  -> Text -- ^ 'vpsRowVpsComment': The comment of the vps.
  -> VpsRow
