-- 1 = Block,  0 = Whitelist
data E'XdpAction
  = E'XdpAction'Num0 -- ^ @0@
  | E'XdpAction'Num1 -- ^ @1@
  deriving (P.Show, P.Eq, P.Typeable, P.Ord, P.Bounded, P.Enum)

instance A.ToJSON E'XdpAction where toJSON = A.toJSON . fromE'XdpAction
instance A.FromJSON E'XdpAction where parseJSON o = P.either P.fail (pure . P.id) . toE'XdpAction =<< A.parseJSON o
instance WH.ToHttpApiData E'XdpAction where toQueryParam = WH.toQueryParam . fromE'XdpAction
instance WH.FromHttpApiData E'XdpAction where parseQueryParam o = WH.parseQueryParam o >>= P.left T.pack . toE'XdpAction
instance MimeRender MimeMultipartFormData E'XdpAction where mimeRender _ = mimeRenderDefaultMultipartFormData

-- | unwrap 'E'XdpAction' enum
fromE'XdpAction :: E'XdpAction -> Int
fromE'XdpAction = \case
  E'XdpAction'Num0 -> 0
  E'XdpAction'Num1 -> 1

-- | parse 'E'XdpAction' enum
toE'XdpAction :: Int -> P.Either String E'XdpAction
toE'XdpAction = \case
  0 -> P.Right E'XdpAction'Num0
  1 -> P.Right E'XdpAction'Num1
  s -> P.Left $ "toE'XdpAction: enum parse failure: " P.++ P.show s


-- * Auth Methods

-- ** AuthApiKeyApiKeyAuth
data AuthApiKeyApiKeyAuth =
  AuthApiKeyApiKeyAuth Text -- ^ secret
  deriving (P.Eq, P.Show, P.Typeable)

instance AuthMethod AuthApiKeyApiKeyAuth where
  applyAuthMethod _ a@(AuthApiKeyApiKeyAuth secret) req =
    P.pure $
    if (P.typeOf a `P.elem` rAuthTypes req)
      then req `setHeader` toHeader ("X-API-KEY", secret)
           & L.over rAuthTypesL (P.filter (/= P.typeOf a))
      else req

-- ** AuthApiKeySessionIdHeaderAuth
data AuthApiKeySessionIdHeaderAuth =
  AuthApiKeySessionIdHeaderAuth Text -- ^ secret
  deriving (P.Eq, P.Show, P.Typeable)

instance AuthMethod AuthApiKeySessionIdHeaderAuth where
  applyAuthMethod _ a@(AuthApiKeySessionIdHeaderAuth secret) req =
    P.pure $
    if (P.typeOf a `P.elem` rAuthTypes req)
      then req `setHeader` toHeader ("sessionid", secret)
           & L.over rAuthTypesL (P.filter (/= P.typeOf a))
      else req

-- ** AuthApiKeySessionIdCookieAuth
data AuthApiKeySessionIdCookieAuth =
  AuthApiKeySessionIdCookieAuth Text -- ^ secret
  deriving (P.Eq, P.Show, P.Typeable)

instance AuthMethod AuthApiKeySessionIdCookieAuth where
  applyAuthMethod _ a@(AuthApiKeySessionIdCookieAuth secret) req =
    P.pure $
    if (P.typeOf a `P.elem` rAuthTypes req)
      then req `setQuery` toQuery ("sessionid", Just secret)
           & L.over rAuthTypesL (P.filter (/= P.typeOf a))
      else req


